/// <summary>
/// PaffH 26.08.21
/// get tableBuffer for EcoResProductTranslation
/// </summary>
/// <param name="_formDataSourceName">str</param>
/// <param name="_itemId">ItemId</param>
/// <param name="_forUpdate">boolean</param>
/// <param name="_result">EventHandlerResult</param>
[SubscribesTo(formStr(EcoResProductCreate), delegateStr(EcoResProductCreate, getBufferByDataSourceNameDelegate))]
public static void EcoResProductCreate_getBufferByDataSourceNameDelegate(str _formDataSourceName, ItemId _itemId, boolean _forUpdate, EventHandlerResult _result)
{
    Common common;
    InventTable inventTable = InventTable::find(_itemId);
    switch (_formDataSourceName)
    {
        case tableStr(EcoResProductTranslation) :
            common = EcoResProductTranslation::findByProductLanguage(inventTable.Product, SystemParameters::getSystemLanguageId(), true);
            break;
        default :
            throw error(Error::wrongUseOfFunction(funcName()));
    }
    _result.result(common);
}
